// TestCLIGraphFileDuplicateFieldsRejected: a graph file that declares a known
// field twice (here upstreams inside one dataset record, and datasets at the
// top level) is ambiguous, so preview, apply, and snapshot must all refuse
// it: non-zero exit, empty stdout, stderr naming the graph file and the
// repeated field. Apply must leave the graph file untouched and snapshot must
// not create its target.
func TestCLIGraphFileDuplicateFieldsRejected(t *testing.T) {
	graphs := map[string]struct {
		data  string
		field string
	}{
		"upstreams twice in record": {`{"datasets":[{"name":"B","upstreams":["A"],"upstreams":[]},{"name":"A","upstreams":[]}]}`, `"upstreams"`},
		"datasets twice":            {`{"datasets":[{"name":"A","upstreams":[]}],"datasets":[]}`, `"datasets"`},
	}
	planPath := writeFile(t, "plan.json", `{"changes":[],"removals":[]}`)

	for name, tc := range graphs {
		t.Run(name, func(t *testing.T) {
			graphPath := writeFile(t, "graph.json", tc.data)
			original := readFile(t, graphPath)
			snapPath := filepath.Join(t.TempDir(), "snap.json")

			stdout, stderr, exit := captureStdout(t, func() int {
				return run([]string{"preview", graphPath, planPath})
			})
			if exit == 0 {
				t.Fatalf("preview succeeded on duplicate-field graph, stdout = %s", stdout)
			}
			if stdout != "" {
				t.Errorf("preview stdout = %q, want empty", stdout)
			}
			if !strings.Contains(stderr, graphPath) || !strings.Contains(stderr, tc.field) {
				t.Errorf("preview stderr = %q, want it to name %q and field %s", stderr, graphPath, tc.field)
			}

			stdout, stderr, exit = captureStdout(t, func() int {
				return run([]string{"apply", graphPath, planPath})
			})
			if exit == 0 {
				t.Fatalf("apply succeeded on duplicate-field graph, stdout = %s", stdout)
			}
			if stdout != "" {
				t.Errorf("apply stdout = %q, want empty", stdout)
			}
			if !strings.Contains(stderr, graphPath) || !strings.Contains(stderr, tc.field) {
				t.Errorf("apply stderr = %q, want it to name %q and field %s", stderr, graphPath, tc.field)
			}
			if got := readFile(t, graphPath); got != original {
				t.Errorf("apply modified the rejected graph file:\n got %s\nwant %s", got, original)
			}

			stdout, stderr, exit = captureStdout(t, func() int {
				return run([]string{"snapshot", graphPath, snapPath})
			})
			if exit == 0 {
				t.Fatalf("snapshot succeeded on duplicate-field graph, stdout = %s", stdout)
			}
			if stdout != "" {
				t.Errorf("snapshot stdout = %q, want empty", stdout)
			}
			if !strings.Contains(stderr, graphPath) || !strings.Contains(stderr, tc.field) {
				t.Errorf("snapshot stderr = %q, want it to name %q and field %s", stderr, graphPath, tc.field)
			}
			if _, err := os.Stat(snapPath); !os.IsNotExist(err) {
				t.Errorf("snapshot target must not be created for a rejected graph, stat err = %v", err)
			}
		})
	}
}

// TestCLIPlanDuplicateFieldsRejected: a plan that declares a known field
// twice (changes or removals at the top level, name or upstreams inside a
// change record) is ambiguous — preview and apply would silently keep only
// the last declaration — so both must refuse it: non-zero exit, empty
// stdout, stderr naming the plan file, the repeated field, and where it
// occurred. The graph and plan files must stay byte-for-byte untouched.
func TestCLIPlanDuplicateFieldsRejected(t *testing.T) {
	plans := map[string]struct {
		data     string
		field    string
		location string
	}{
		"changes twice": {
			`{"changes":[{"name":"A","upstreams":["B"]}],"changes":[]}`,
			`"changes"`, "top level",
		},
		"removals twice": {
			`{"removals":["A"],"removals":[]}`,
			`"removals"`, "top level",
		},
		"name twice in record": {
			`{"changes":[{"name":"A","name":"B","upstreams":[]}]}`,
			`"name"`, `index 0 of "changes"`,
		},
		"upstreams twice in record": {
			`{"changes":[{"name":"B","upstreams":["A"],"upstreams":[]}]}`,
			`"upstreams"`, `index 0 of "changes"`,
		},
		"case variant changes": {
			`{"Changes":[],"changes":[{"name":"A","upstreams":[]}]}`,
			`"changes"`, "top level",
		},
	}
	graphData := `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`

	for name, tc := range plans {
		t.Run(name, func(t *testing.T) {
			graphPath := writeFile(t, "graph.json", graphData)
			planPath := writeFile(t, "plan.json", tc.data)
			graphBefore := readFile(t, graphPath)
			planBefore := readFile(t, planPath)

			stdout, stderr, exit := captureStdout(t, func() int {
				return run([]string{"preview", graphPath, planPath})
			})
			if exit == 0 {
				t.Fatalf("preview succeeded on duplicate-field plan, stdout = %s", stdout)
			}
			if stdout != "" {
				t.Errorf("preview stdout = %q, want empty", stdout)
			}
			if !strings.Contains(stderr, planPath) || !strings.Contains(stderr, tc.field) || !strings.Contains(stderr, tc.location) {
				t.Errorf("preview stderr = %q, want it to name %q, field %s, and location %q", stderr, planPath, tc.field, tc.location)
			}

			stdout, stderr, exit = captureStdout(t, func() int {
				return run([]string{"apply", graphPath, planPath})
			})
			if exit == 0 {
				t.Fatalf("apply succeeded on duplicate-field plan, stdout = %s", stdout)
			}
			if stdout != "" {
				t.Errorf("apply stdout = %q, want empty", stdout)
			}
			if !strings.Contains(stderr, planPath) || !strings.Contains(stderr, tc.field) || !strings.Contains(stderr, tc.location) {
				t.Errorf("apply stderr = %q, want it to name %q, field %s, and location %q", stderr, planPath, tc.field, tc.location)
			}

			if got := readFile(t, graphPath); got != graphBefore {
				t.Errorf("graph file changed after rejected plan:\n got %s\nwant %s", got, graphBefore)
			}
			if got := readFile(t, planPath); got != planBefore {
				t.Errorf("plan file changed after rejection:\n got %s\nwant %s", got, planBefore)
			}
		})
	}
}

//go:build unix

package main

import (
	"os"
	"syscall"
)

// fileLock is an exclusive, process-advisory lock guarding a snapshot target
// against concurrent saves. It serializes the check-existing-then-write
// sequence so two simultaneous saves of different content can never both
// "win": the first writes, the second observes the existing content and
// refuses, and two saves of identical content both succeed without rewriting
// the file.
type fileLock struct {
	f *os.File
}

// acquireLock creates the lock file if needed and blocks until an exclusive
// lock is held.
func acquireLock(path string) (*fileLock, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return nil, err
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
		f.Close()
		return nil, err
	}
	return &fileLock{f: f}, nil
}

// release unlocks and closes the lock file; the file itself is left behind so
// future saves can lock the same stable path.
func (l *fileLock) release() {
	_ = syscall.Flock(int(l.f.Fd()), syscall.LOCK_UN)
	_ = l.f.Close()
}

//go:build !unix

package main

// fileLock is a no-op on platforms without flock. Concurrent-save safety is
// provided on unix hosts, which is the supported offline environment; on other
// platforms saves still validate and atomically rename, they simply cannot
// cross-process serialize.
type fileLock struct{}

func acquireLock(path string) (*fileLock, error) { return &fileLock{}, nil }

func (l *fileLock) release() {}

