	roDir, _ := os.MkdirTemp("", "rodir-*")
	target := filepath.Join(roDir, "graph.json")
	if err := os.WriteFile(target, []byte("OLD"), 0o644); err != nil {
		panic(err)
	}
	if err := os.Chmod(roDir, 0o555); err != nil {
		panic(err)
	}
	_, err = os.CreateTemp(roDir, ".chainledger-*")
	fmt.Printf("mode1 CreateTemp: err=%v isEACCES=%v\n", err, errors.Is(err, syscall.EACCES))
	os.Chmod(roDir, 0o755)

	// Failure mode 2: temp written, rename cannot replace across devices.
	wDir, _ := os.MkdirTemp("", "wdir-*")           // ext4 (TMPDIR unset -> /tmp)
	oDir, _ := os.MkdirTemp("/dev/shm", "odir-*")  // tmpfs, different device
	realFile := filepath.Join(oDir, "graph.json")
	if err := os.WriteFile(realFile, []byte("OLD-BYTES"), 0o644); err != nil {
		panic(err)
	}
	link := filepath.Join(wDir, "graph.json")
	if err := os.Symlink(realFile, link); err != nil {
		panic(err)
	}
	// reading via link works:
	b, rerr := os.ReadFile(link)
	fmt.Printf("mode2 read via symlink: bytes=%q err=%v\n", string(b), rerr)
	t2, cerr := os.CreateTemp(wDir, ".chainledger-*")
	fmt.Printf("mode2 CreateTemp in link dir: err=%v\n", cerr)
	if cerr == nil {
		t2.WriteString("NEW-BYTES")
		t2.Close()
		rerr := os.Rename(t2.Name(), link)
		fmt.Printf("mode2 Rename: err=%v isEXDEV=%v\n", rerr, errors.Is(rerr, syscall.EXDEV))
		// after failure, original intact and temp cleaned by production; check original:
		after, _ := os.ReadFile(link)
		fmt.Printf("mode2 original after failed rename: %q\n", string(after))
		os.Remove(t2.Name())
	}
}

